(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const errs = () => (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').trim()).filter(t=>/invalid|incorrect|wrong|expired|failed|not.*match/i.test(t) && t.length<90).slice(0,5));
  const first = document.getElementById('first');
  if (!first) return JSON.stringify({stage:'noFirst'});
  // find hidden ancestor
  let cur = first;
  const chain = [];
  for (let i = 0; i < 10 && cur; i++) {
    const cs = getComputedStyle(cur);
    chain.push({tag: cur.tagName, id: cur.id, cls: (cur.className||'').toString().slice(0,40), display: cs.display, hiddenAttr: cur.hasAttribute('hidden')});
    if (cs.display === 'none' || cur.hasAttribute('hidden')) {
      cur.style.display = 'block';
      cur.removeAttribute('hidden');
      cur.style.visibility = 'visible';
    }
    cur = cur.parentElement;
  }
  await sleep(1500);
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i => /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'') && i.offsetParent !== null);
  if (!boxes.length) return JSON.stringify({stage:'stillHidden', chain, errs: errs()});
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  const digits = '8751';
  for (let i = 0; i < boxes.length; i++) {
    setter.call(boxes[i], i < digits.length ? digits[i] : '');
    boxes[i].dispatchEvent(new Event('input', {bubbles:true}));
    boxes[i].dispatchEvent(new Event('change', {bubbles:true}));
  }
  await sleep(400);
  const c2 = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test(b.innerText||''));
  if (c2) { c2.click(); await sleep(9000); }
  return JSON.stringify({stage:'filled', url: location.href, errs: errs(), inputNow: Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null).map(i=>i.id).slice(0,10)});
})()
